from collections.abc import Mapping
from copy import deepcopy


def select_runtime_commands(commands, runtime):
    if not isinstance(runtime, str):
        raise TypeError("runtime must be a string")
    if not runtime:
        raise ValueError("runtime cannot be empty")
    if isinstance(commands, (str, bytes)):
        raise TypeError("commands must be a non-string iterable")
    try:
        items = list(commands)
    except TypeError as exc:
        raise TypeError("commands must be iterable") from exc
    wanted = runtime.casefold()
    result = []
    for item in items:
        if not isinstance(item, Mapping):
            raise TypeError("each command must be a mapping")
        if set(item) != {"command", "runtime", "enabled"}:
            raise ValueError("command contains missing or unexpected keys")
        if not isinstance(item["command"], str) or not isinstance(item["runtime"], str):
            raise TypeError("command and runtime values must be strings")
        if not item["command"] or not item["runtime"]:
            raise ValueError("command and runtime values cannot be empty")
        if type(item["enabled"]) is not bool:
            raise TypeError("enabled must be a boolean")
        if item["enabled"] and item["runtime"].casefold() is wanted:
            result.append(deepcopy(dict(item)))
    return result
```

